import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.CWCEHGF4.js";const n="/MeshPaintingDoc/multiplayer/01-target-replication-settings.png",r="/MeshPaintingDoc/multiplayer/02-actor-replication.png",l="/MeshPaintingDoc/multiplayer/03-controller-component.png",s="/MeshPaintingDoc/multiplayer/04-set-paint-target-component.png",c="/MeshPaintingDoc/multiplayer/05-pie-multiplayer-settings.png",p="/MeshPaintingDoc/multiplayer/06-live-replication-result.png",f=JSON.parse('{"title":"Multiplayer","description":"","frontmatter":{},"headers":[],"relativePath":"systems/multiplayer.md","filePath":"systems/multiplayer.md","lastUpdated":1784811592000}'),d={name:"systems/multiplayer.md"};function h(m,e,u,g,y,b){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="multiplayer" tabindex="-1">Multiplayer <a class="header-anchor" href="#multiplayer" aria-label="Permalink to &quot;Multiplayer&quot;">​</a></h1><p>Runtime Mesh Painting replicates paint commands, not render target textures.</p><p>Each client receives the accepted paint commands and applies them locally through the same GPU paint path. This keeps bandwidth low and also lets late-joining players rebuild the painted state from history.</p><h2 id="multiplayer-quick-start" tabindex="-1">Multiplayer Quick Start <a class="header-anchor" href="#multiplayer-quick-start" aria-label="Permalink to &quot;Multiplayer Quick Start&quot;">​</a></h2><h3 id="_1-set-up-the-paintable-mesh" tabindex="-1">1. Set Up the Paintable Mesh <a class="header-anchor" href="#_1-set-up-the-paintable-mesh" aria-label="Permalink to &quot;1. Set Up the Paintable Mesh&quot;">​</a></h3><p>Set up the mesh the same way as the normal <a href="/MeshPaintingDoc/guide/quick-start">Quick Start</a>:</p><ul><li>Add <code>RuntimeMeshPaintTargetComponent</code> to the mesh actor.</li><li>Set up the mesh material with the <code>Mesh Painting</code> material function.</li><li>Make sure the mesh blocks the painting trace channel, usually <code>Visibility</code>.</li><li>Make sure the material <code>UV Index</code> matches the target component <code>UVChannel</code>.</li></ul><h3 id="_2-enable-runtime-paint-replication" tabindex="-1">2. Enable Runtime Paint Replication <a class="header-anchor" href="#_2-enable-runtime-paint-replication" aria-label="Permalink to &quot;2. Enable Runtime Paint Replication&quot;">​</a></h3><p>On <code>RuntimeMeshPaintTargetComponent</code>, keep <code>Replicate Runtime Paint</code> enabled.</p><p>The default values are enough for a first multiplayer test:</p><ul><li><code>Replicate Runtime Paint</code> enables command replication for this paint target.</li><li><code>Auto Enable Owner Replication</code> allows the component to enable replication on the owner actor at runtime.</li><li><code>Max Replicated Paint Commands = 0</code> keeps the full command history, which is the safest setting for late join.</li><li><code>Replicated Paint Replay Commands Per Tick</code> controls how many stored commands a joining client replays per tick.</li><li><code>Max Replicated Paint Distance = 0</code> disables distance validation.</li><li><code>Max Replicated Brush Size</code> limits the largest brush size accepted by the server.</li></ul><p><img src="'+n+'" alt="Runtime paint replication settings"></p><h3 id="_3-make-sure-the-target-actor-replicates" tabindex="-1">3. Make Sure the Target Actor Replicates <a class="header-anchor" href="#_3-make-sure-the-target-actor-replicates" aria-label="Permalink to &quot;3. Make Sure the Target Actor Replicates&quot;">​</a></h3><p>The actor that owns the paint target should replicate. <code>Auto Enable Owner Replication</code> can handle this on authority, but it is still a good idea to verify the actor&#39;s replication settings while setting up the level.</p><p><img src="'+r+'" alt="Actor replication settings"></p><h3 id="_4-add-the-painting-controller" tabindex="-1">4. Add the Painting Controller <a class="header-anchor" href="#_4-add-the-painting-controller" aria-label="Permalink to &quot;4. Add the Painting Controller&quot;">​</a></h3><p>Add <code>PaintingModeControllerComponent</code> to the player pawn, character, or player-owned controller that handles painting input.</p><p>This is important because client-to-server paint RPCs must come from an owned actor/component. The paint target in the world may not be owned by the painting client, so the controller component is the correct entry point for multiplayer painting.</p><p><img src="'+l+'" alt="Painting controller component"></p><h3 id="_5-optional-limit-which-targets-the-controller-can-paint" tabindex="-1">5. Optional: Limit Which Targets the Controller Can Paint <a class="header-anchor" href="#_5-optional-limit-which-targets-the-controller-can-paint" aria-label="Permalink to &quot;5. Optional: Limit Which Targets the Controller Can Paint&quot;">​</a></h3><p>You do not need to assign a target filter for a basic multiplayer test.</p><p>If no filter is configured, the controller can paint any valid <code>RuntimeMeshPaintTargetComponent</code> it hits.</p><p>If you want to limit painting to specific targets, set it from Blueprint or C++ using the controller functions such as <code>SetPaintTargetComponent</code>, <code>SetPaintTargetComponents</code>, or <code>AddPaintTargetComponent</code>.</p><p><img src="'+s+'" alt="Set Paint Target Component node"></p><h3 id="_6-test-with-two-players" tabindex="-1">6. Test With Two Players <a class="header-anchor" href="#_6-test-with-two-players" aria-label="Permalink to &quot;6. Test With Two Players&quot;">​</a></h3><p>In Play settings, start with two players and use a listen server setup for a simple local test.</p><p><img src="'+c+'" alt="PIE multiplayer settings"></p><p>Paint from one player and confirm that the same paint appears for the other player.</p><p><img src="'+p+'" alt="Live multiplayer paint replication result"></p><h3 id="_7-test-late-join" tabindex="-1">7. Test Late Join <a class="header-anchor" href="#_7-test-late-join" aria-label="Permalink to &quot;7. Test Late Join&quot;">​</a></h3><p>After live replication works, test a player joining after paint already exists.</p><p>For late join to work correctly, keep <code>Max Replicated Paint Commands</code> at <code>0</code> unless you have your own checkpoint or save system. A value of <code>0</code> keeps the full command history so a new client can rebuild the current paint state.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><h3 id="command-replication" tabindex="-1">Command Replication <a class="header-anchor" href="#command-replication" aria-label="Permalink to &quot;Command Replication&quot;">​</a></h3><p>The plugin does not send render target pixels over the network.</p><p>Instead, every accepted paint action is stored as a compact command containing the target, mesh target index, UV channel, stroke id, brush ray, brush center, brush normal, brush size, color, material settings, erase flag, and optional screen projection data.</p><p>Skeletal mesh paint commands include screen projection data. This lets every client reproduce the same GPU projected brush result without relying on per-poly collision, <code>FindCollisionUV</code>, or the old CPU skeletal UV fallback path.</p><h3 id="local-prediction" tabindex="-1">Local Prediction <a class="header-anchor" href="#local-prediction" aria-label="Permalink to &quot;Local Prediction&quot;">​</a></h3><p>When a local player paints, the controller applies the paint immediately on that client for responsive feedback.</p><p>The same command is then sent to the server. When the server accepts it, other clients receive and apply the command locally. The original painting client skips duplicate application of its own predicted command.</p><p>Changing color, metallic, roughness, brush size, or eraser state only updates local brush settings. A history entry is created only when an actual paint command is applied.</p><h3 id="server-validation" tabindex="-1">Server Validation <a class="header-anchor" href="#server-validation" aria-label="Permalink to &quot;Server Validation&quot;">​</a></h3><p>The server validates incoming commands before adding them to history.</p><p>Validation checks include:</p><ul><li>Runtime paint replication is enabled.</li><li>The command targets the correct component.</li><li>The command uses the same <code>UVChannel</code> as the target component.</li><li>The mesh target index is valid.</li><li>The brush size is within <code>Max Replicated Brush Size</code>.</li><li>The brush ray and normal are valid.</li><li>Skeletal mesh commands include valid screen projection data.</li><li>Optional distance validation passes when <code>Max Replicated Paint Distance</code> is greater than <code>0</code>.</li></ul><h3 id="late-join-replay" tabindex="-1">Late Join Replay <a class="header-anchor" href="#late-join-replay" aria-label="Permalink to &quot;Late Join Replay&quot;">​</a></h3><p>Late-joining clients initialize their local runtime render targets, receive the replicated command history, and replay the commands over multiple ticks.</p><p><code>Replicated Paint Replay Commands Per Tick</code> controls how quickly the history is replayed. Higher values catch up faster, while lower values reduce hitch risk when the history is large.</p><p>Replicated commands are queued by <code>CommandId</code> before replay. If a command cannot be applied yet because the local runtime target is not ready, replay pauses instead of dropping the command.</p><h3 id="dedicated-server-behavior" tabindex="-1">Dedicated Server Behavior <a class="header-anchor" href="#dedicated-server-behavior" aria-label="Permalink to &quot;Dedicated Server Behavior&quot;">​</a></h3><p>Dedicated servers do not render paint textures.</p><p>They only receive paint commands, validate them, assign command ids, store the authoritative command history, and replicate that history to clients. The visible paint result is generated on clients and listen-server hosts.</p><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li>The paint target actor does not replicate.</li><li><code>Replicate Runtime Paint</code> is disabled on the target component.</li><li><code>Max Replicated Paint Commands</code> is set to a small value, then late join cannot rebuild older paint.</li><li>The material <code>UV Index</code> and target component <code>UVChannel</code> do not match.</li><li>The mesh does not block the painting trace channel.</li><li>The painting controller is not on a player-owned actor/component.</li></ul>',54)])])}const k=t(d,[["render",h]]);export{f as __pageData,k as default};
